/**
 * 真实分层产物的像素 fixture（勿手改）。
 *
 * 来源：2026-08-10 在预览环境跑的真实分层任务 run 751ad868aabf41da98065dfd4ea1818f
 *（模型 image-layering / fal qwen-image-layered，原图 1024x1024 深色产品海报，请求 4 层、返回 4 层）。
 * 每项是该图在 Chromium 里按生产同一口径缩到 48x48 后的 RGBA 原始字节的 base64。
 *
 * 为什么存真像素而不是构造数据：上一版判据在构造数据上全绿，一碰真实产物就 0 命中——
 * 「近乎纯色的背景层」这种形状是构造不出来的，只有真图里才有。
 * 重新生成：scripts 见 doc 说明，或重跑一次分层后用同样的 48x48 采样导出。
 */
export const REAL_LAYER_FIXTURE_BASE64 = {
  source: '',
  layer0: '',
  layer1: '',
  layer2: '',
  layer3: '',
} as const;

/** base64 → RGBA。测试环境没有 canvas，所以 fixture 存的是解好的像素而不是 PNG。 */
export function decodeFixture(b64: string): Uint8ClampedArray {
  const bin = typeof atob === 'function' ? atob(b64) : Buffer.from(b64, 'base64').toString('binary');
  const out = new Uint8ClampedArray(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}
